BEGIN;
ALTER TABLE items
  ADD COLUMN IF NOT EXISTS packaging text,
  ADD COLUMN IF NOT EXISTS uom text;
UPDATE items SET packaging = '5g.', uom = 'sachet', cost = 13.55, sales_price = COALESCE(sales_price, 18.97), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 21.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "5g.", "sheet_row": 5}'::jsonb WHERE name = 'Coccibuster';
