UPDATE items SET packaging = '5g.', uom = 'sachet', cost = 14.19, sales_price = COALESCE(sales_price, 19.87), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 22.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "5g.", "sheet_row": 16}'::jsonb WHERE name = 'Robistrep Vk 5Gm';
UPDATE items SET packaging = '5g.', uom = 'sachet', cost = 7.74, sales_price = COALESCE(sales_price, 10.84), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 12.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "5g.", "sheet_row": 18}'::jsonb WHERE name = 'Wormbuster Single Dose 5Gm';
UPDATE items SET packaging = '100 ml', uom = 'bottle', cost = 281.27, sales_price = COALESCE(sales_price, 393.78), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 436.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "100 ml", "sheet_row": 25}'::jsonb WHERE name = 'Robi L.A inj 100ml';
UPDATE items SET packaging = '10 ds w/ diluent', uom = 'bottle', cost = 78.7, sales_price = COALESCE(sales_price, 110.19), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 122.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "10 ds w/ diluent", "sheet_row": 27}'::jsonb WHERE name = 'Robipenstrep P 10dose/Diluent';
UPDATE items SET packaging = 'Single dose', uom = 'bottle', cost = 28.39, sales_price = COALESCE(sales_price, 39.74), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 44.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "Single dose", "sheet_row": 28}'::jsonb WHERE name = 'Robipenstrep P Single dose bt';
