UPDATE items SET packaging = '100 ml', uom = 'bottle', cost = 256.11, sales_price = COALESCE(sales_price, 358.56), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 397.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "100 ml", "sheet_row": 31}'::jsonb WHERE name = 'Robicomject inj 100ml';
UPDATE items SET packaging = '2 x 100ml (disp.)', uom = 'bottle', cost = 248.37, sales_price = COALESCE(sales_price, 347.72), deal = COALESCE(deal, '10 + 2'), price_breakdown = '{"invoice": 385.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "2 x 100ml (disp.)", "sheet_row": 32}'::jsonb WHERE name = 'Tripulac Pig Doser 2x1 set';
UPDATE items SET packaging = '300g x 12/box', uom = 'box', cost = 710.2, sales_price = COALESCE(sales_price, 994.28), deal = COALESCE(deal, NULL), price_breakdown = '{"invoice": 1050.0, "less": [0.2, 0.1, 0.2], "vat": "add_12", "srp_markup": 1.4, "packaging": "300g", "sheet_row": 37}'::jsonb WHERE name = 'Wheatgerm 300Gm x 12/box';

UPDATE items SET uom = 'bag'    WHERE uom IS NULL AND (name ILIKE '%(50KG)%' OR name ILIKE '%(25KG)%' OR name ILIKE '%(20KG)%' OR name ILIKE '%(5KG)%' OR name ILIKE '%(25x1kg)%');
UPDATE items SET uom = 'box'    WHERE uom IS NULL AND (name ILIKE '%box%' OR name ILIKE '%x12%' OR name ILIKE '%x10%' OR name ILIKE '%x 12%' OR notes ILIKE '%Unit: box%');
UPDATE items SET uom = 'carton' WHERE uom IS NULL AND notes ILIKE '%Unit: carton%';
UPDATE items SET uom = 'bundle' WHERE uom IS NULL AND name ILIKE '%(10Lx3)%';
UPDATE items SET uom = 'piece'  WHERE uom IS NULL;
COMMIT;
SELECT category, count(*) AS items FROM items GROUP BY category ORDER BY 1;
SELECT 'total: '||count(*) FROM items;